import React from 'react';
import { ComponentType, FunctionCircuit } from '../types';
import { COMPONENT_DEFINITIONS } from '../constants';

interface SidebarProps {
  selectedTool: 'SELECT' | 'DELETE';
  onSelectTool: (t: 'SELECT' | 'DELETE') => void;
  onTouchStartItem?: (type: ComponentType, e: React.TouchEvent, functionId?: string) => void;
  functionLibrary: FunctionCircuit[];
}

const Sidebar: React.FC<SidebarProps> = ({ selectedTool, onSelectTool, onTouchStartItem, functionLibrary }) => {
  const groups = [
    { name: 'I/O', items: [ComponentType.INPUT_SWITCH, ComponentType.OUTPUT_LED, ComponentType.CLOCK, ComponentType.HEX_DISPLAY] },
    { name: 'Gates', items: [ComponentType.NOT, ComponentType.AND, ComponentType.OR, ComponentType.NAND, ComponentType.NOR, ComponentType.XOR] },
    { name: 'Routing', items: [ComponentType.SPLITTER, ComponentType.MERGER] }
  ];

  const handleDragStart = (e: React.DragEvent, type: ComponentType, functionId?: string) => {
    e.dataTransfer.setData('application/react-logic-sim', JSON.stringify({ type, functionId }));
    e.dataTransfer.effectAllowed = 'copy';
  };

  const draggableFunctions = functionLibrary.filter(f => f.id !== 'main');

  return (
    <div className="w-64 bg-white border-r border-slate-200 flex flex-col h-full shadow-lg z-10">
      <div className="p-4 border-b border-slate-100">
        <h1 className="text-xl font-bold text-slate-800 tracking-tight">LogicFlow</h1>
        <p className="text-xs text-slate-400 mt-1">Simulator v1.4 (Bus)</p>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6">

        {/* Tools */}
        <div>
          <h3 className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-3">Tools</h3>
          <div className="grid grid-cols-2 gap-2">
            <button
              onClick={() => onSelectTool('SELECT')}
              className={`p-2 rounded text-sm font-medium transition-colors ${selectedTool === 'SELECT' ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
            >
              Cursor
            </button>
            <button
              onClick={() => onSelectTool('DELETE')}
              className={`p-2 rounded text-sm font-medium transition-colors ${selectedTool === 'DELETE' ? 'bg-red-500 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
            >
              Delete
            </button>
          </div>
        </div>

        {/* Components */}
        {groups.map(group => (
          <div key={group.name}>
            <h3 className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-3">{group.name}</h3>
            <div className="grid grid-cols-2 gap-3">
              {group.items.map(type => {
                const def = COMPONENT_DEFINITIONS[type];
                return (
                  <div
                    key={type}
                    draggable={true}
                    onDragStart={(e) => handleDragStart(e, type)}
                    onTouchStart={(e) => onTouchStartItem && onTouchStartItem(type, e)}
                    className="flex flex-col items-center justify-center p-3 rounded border-2 border-slate-100 bg-white hover:border-slate-300 hover:shadow-sm transition-all duration-200 cursor-grab active:cursor-grabbing touch-none"
                  >
                    <div className="w-8 h-8 mb-2 border border-slate-300 rounded flex items-center justify-center bg-white text-[10px] font-bold text-slate-600 pointer-events-none">
                      {def.label.substring(0,5)}
                    </div>
                    <span className="text-xs font-medium text-slate-700 pointer-events-none">{def.label}</span>
                  </div>
                );
              })}
            </div>
          </div>
        ))}

        {/* Custom Functions */}
        {draggableFunctions.length > 0 && (
            <div>
                 <h3 className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-3">My Functions</h3>
                 <div className="grid grid-cols-1 gap-2">
                    {draggableFunctions.map(func => (
                        <div
                            key={func.id}
                            draggable={true}
                            onDragStart={(e) => handleDragStart(e, ComponentType.CUSTOM_IC, func.id)}
                            onTouchStart={(e) => onTouchStartItem && onTouchStartItem(ComponentType.CUSTOM_IC, e, func.id)}
                            className="flex items-center p-2 rounded border border-slate-200 bg-blue-50 hover:border-blue-300 hover:shadow-sm transition-all duration-200 cursor-grab active:cursor-grabbing touch-none"
                        >
                             <div className="w-6 h-6 mr-3 border border-blue-200 rounded flex items-center justify-center bg-white text-[9px] font-bold text-blue-600 pointer-events-none">
                                IC
                             </div>
                             <span className="text-sm font-medium text-slate-700 pointer-events-none truncate">{func.name}</span>
                        </div>
                    ))}
                 </div>
            </div>
        )}

      </div>
    </div>
  );
};

export default Sidebar;

import React, { useState, useRef, useEffect, useLayoutEffect } from 'react';
import Sidebar from './components/Sidebar';
import LogicCanvas, { LogicCanvasHandle } from './components/LogicCanvas';
import { ComponentType, CircuitComponent, Wire, FunctionCircuit } from './types';
import { COMPONENT_DEFINITIONS } from './constants';

const LOCAL_STORAGE_KEY = 'logicflow_autosave_v1';
const LOCAL_STORAGE_ID_KEY = 'logicflow_active_id_v1';

const App: React.FC = () => {
  const [selectedTool, setSelectedTool] = useState<'SELECT' | 'DELETE'>('SELECT');
  const [isPlaying, setIsPlaying] = useState(false); 
  const [tickSpeed, setTickSpeed] = useState(50); 

  const [functions, setFunctions] = useState<FunctionCircuit[]>(() => {
    try {
      const saved = localStorage.getItem(LOCAL_STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed) && parsed.length > 0) {
          return parsed;
        }
      }
    } catch (e) {
      console.error("Failed to load autosave", e);
    }
    return [{ id: 'main', name: 'Main Circuit', components: [], wires: [] }];
  });

  const [activeFunctionId, setActiveFunctionId] = useState<string>(() => {
    try {
        const savedId = localStorage.getItem(LOCAL_STORAGE_ID_KEY);
        if (savedId) return savedId;
    } catch(e) {}
    return 'main';
  });

  useLayoutEffect(() => {
    if (!functions.find(f => f.id === activeFunctionId)) {
        setActiveFunctionId(functions[0]?.id || 'main');
    }
  }, [functions, activeFunctionId]);

  const [dataVersion, setDataVersion] = useState(0);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newFuncName, setNewFuncName] = useState("");
  const [isProjectMenuOpen, setIsProjectMenuOpen] = useState(false);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);

  const [selectedComponent, setSelectedComponent] = useState<CircuitComponent | null>(null);
  const [tempLabel, setTempLabel] = useState("");

  const [draggedType, setDraggedType] = useState<ComponentType | null>(null);
  const [draggedFuncId, setDraggedFuncId] = useState<string | undefined>(undefined);
  const [dragPos, setDragPos] = useState<{x: number, y: number} | null>(null);
  const [pendingDrop, setPendingDrop] = useState<{type: ComponentType, x: number, y: number, functionId?: string} | null>(null);

  const canvasWrapperRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<LogicCanvasHandle>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const functionsRef = useRef(functions);
  const activeIdRef = useRef(activeFunctionId);

  useEffect(() => { functionsRef.current = functions; }, [functions]);
  useEffect(() => { activeIdRef.current = activeFunctionId; }, [activeFunctionId]);

  const activeFunction = functions.find(f => f.id === activeFunctionId) || functions[0];

  const persistToStorage = () => {
    let currentData = functionsRef.current;
    if (canvasRef.current) {
        const { components, wires } = canvasRef.current.getData();
        const activeId = activeIdRef.current;
        currentData = currentData.map(f => 
            f.id === activeId 
              ? { ...f, components: [...components], wires: [...wires] } 
              : f
        );
    }
    try {
        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(currentData));
        localStorage.setItem(LOCAL_STORAGE_ID_KEY, activeIdRef.current);
        setLastSaved(new Date());
    } catch (e) {
        console.error("Autosave failed", e);
    }
  };

  useEffect(() => {
    const interval = setInterval(persistToStorage, 5000);
    const handleVisibilityChange = () => { if (document.hidden) persistToStorage(); };
    document.addEventListener("visibilitychange", handleVisibilityChange);
    const handleBeforeUnload = () => { persistToStorage(); };
    window.addEventListener("beforeunload", handleBeforeUnload);

    return () => {
        clearInterval(interval);
        document.removeEventListener("visibilitychange", handleVisibilityChange);
        window.removeEventListener("beforeunload", handleBeforeUnload);
        persistToStorage();
    };
  }, []);

  const handleTouchStartItem = (type: ComponentType, e: React.TouchEvent, functionId?: string) => {
    const touch = e.touches[0];
    setDraggedType(type);
    setDraggedFuncId(functionId);
    setDragPos({ x: touch.clientX, y: touch.clientY });
  };

  useEffect(() => {
    const handleTouchMove = (e: TouchEvent) => {
      if (draggedType) {
        e.preventDefault(); 
        const touch = e.touches[0];
        setDragPos({ x: touch.clientX, y: touch.clientY });
      }
    };

    const handleTouchEnd = (e: TouchEvent) => {
      if (draggedType && dragPos && canvasWrapperRef.current) {
        const rect = canvasWrapperRef.current.getBoundingClientRect();
        if (
          dragPos.x >= rect.left &&
          dragPos.x <= rect.right &&
          dragPos.y >= rect.top &&
          dragPos.y <= rect.bottom
        ) {
          const relX = dragPos.x - rect.left;
          const relY = dragPos.y - rect.top;
          setPendingDrop({ type: draggedType, x: relX, y: relY, functionId: draggedFuncId });
        }
      }
      setDraggedType(null);
      setDraggedFuncId(undefined);
      setDragPos(null);
    };

    if (draggedType) {
      window.addEventListener('touchmove', handleTouchMove, { passive: false });
      window.addEventListener('touchend', handleTouchEnd);
    }

    return () => {
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
    };
  }, [draggedType, dragPos, draggedFuncId]);

  const handlePendingDropHandled = () => {
    setPendingDrop(null);
  };

  const getLatestFunctionsState = (): FunctionCircuit[] => {
    if (canvasRef.current) {
      const { components, wires } = canvasRef.current.getData();
      return functions.map(f => 
        f.id === activeFunctionId 
          ? { ...f, components: [...components], wires: [...wires] }
          : f
      );
    }
    return functions;
  };

  const saveCurrentState = () => {
    const updated = getLatestFunctionsState();
    setFunctions(updated);
    try {
        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(updated));
        localStorage.setItem(LOCAL_STORAGE_ID_KEY, activeFunctionId);
        setLastSaved(new Date());
    } catch(e) {}
    return updated;
  };

  const switchToFunction = (id: string) => {
    if (id === activeFunctionId) return;
    saveCurrentState();
    setSelectedComponent(null);
    setActiveFunctionId(id);
    setIsPlaying(false);
  };

  const handleQuickSave = () => {
    persistToStorage();
    setIsProjectMenuOpen(false);
  };

  const handleClearStorage = () => {
    if (confirm("Clear local saved data? This will reset the project.")) {
        localStorage.removeItem(LOCAL_STORAGE_KEY);
        localStorage.removeItem(LOCAL_STORAGE_ID_KEY);
        const defaultState = [{ id: 'main', name: 'Main Circuit', components: [], wires: [] }];
        setFunctions(defaultState);
        setActiveFunctionId('main');
        setDataVersion(v => v + 1);
    }
    setIsProjectMenuOpen(false);
  };

  const downloadJSON = (data: any, filename: string) => {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleExportProject = () => {
    const data = getLatestFunctionsState();
    downloadJSON(data, `logicflow_project_${new Date().getTime()}.json`);
    setIsProjectMenuOpen(false);
  };

  const handleExportFunction = () => {
    if (canvasRef.current) {
        const { components, wires } = canvasRef.current.getData();
        const funcData: FunctionCircuit = {
            ...activeFunction,
            components,
            wires
        };
        downloadJSON(funcData, `${activeFunction.name.replace(/\s+/g, '_')}_function.json`);
    }
    setIsProjectMenuOpen(false);
  };

  const triggerFileUpload = () => {
    fileInputRef.current?.click();
    setIsProjectMenuOpen(false);
  };

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const content = e.target?.result as string;
            const parsed = JSON.parse(content);

            if (Array.isArray(parsed)) {
                if (parsed.length > 0 && parsed[0].id && parsed[0].components) {
                    if (confirm("This will replace your current project. Continue?")) {
                        setFunctions(parsed);
                        setActiveFunctionId(parsed[0].id);
                        setSelectedComponent(null);
                        setIsPlaying(false);
                        setDataVersion(v => v + 1);
                        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(parsed));
                        localStorage.setItem(LOCAL_STORAGE_ID_KEY, parsed[0].id);
                    }
                } else {
                    alert("Invalid Project File");
                }
            } else if (typeof parsed === 'object' && parsed.id && parsed.components) {
                const newFunc = parsed as FunctionCircuit;
                const existing = functions.find(f => f.id === newFunc.id);
                if (existing) {
                    newFunc.id = crypto.randomUUID();
                    newFunc.name = `${newFunc.name} (Imported)`;
                }
                const currentData = getLatestFunctionsState();
                const newData = [...currentData, newFunc];
                setFunctions(newData);
                localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(newData));
                alert(`Imported function: ${newFunc.name}`);
            } else {
                alert("Unknown file format.");
            }
        } catch (err) {
            console.error(err);
            alert("Failed to parse JSON file.");
        }
        if (fileInputRef.current) fileInputRef.current.value = "";
    };
    reader.readAsText(file);
  };

  const openNewFunctionModal = () => {
    setNewFuncName("");
    setIsModalOpen(true);
  };

  const submitNewFunction = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newFuncName.trim()) return;
    const currentData = saveCurrentState(); 
    const newId = crypto.randomUUID();
    const newFunc: FunctionCircuit = {
      id: newId,
      name: newFuncName,
      components: [],
      wires: []
    };
    const nextState = [...currentData, newFunc];
    setFunctions(nextState);
    setActiveFunctionId(newId);
    setIsModalOpen(false);
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(nextState));
    localStorage.setItem(LOCAL_STORAGE_ID_KEY, newId);
  };

  const deleteFunction = (id: string) => {
    if (id === 'main') {
      alert("Cannot delete Main Circuit");
      return;
    }
    if (confirm("Are you sure you want to delete this function?")) {
      const nextState = functions.filter(f => f.id !== id);
      setFunctions(nextState);
      localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(nextState));
      if (activeFunctionId === id) {
        setActiveFunctionId('main');
        localStorage.setItem(LOCAL_STORAGE_ID_KEY, 'main');
      }
    }
  };

  const handleSelectionChange = (comp: CircuitComponent | null) => {
      setSelectedComponent(comp);
      if (comp) {
          setTempLabel(comp.customLabel || (comp.type === ComponentType.INPUT_SWITCH ? "IN" : (comp.type === ComponentType.OUTPUT_LED ? "OUT" : "")));
      } else {
        setTempLabel("");
      }
  };

  const updateLabel = (val: string) => {
      setTempLabel(val);
      updateComponentProp({ customLabel: val });
  };

  const updateComponentProp = (updates: Partial<CircuitComponent>) => {
    if (selectedComponent && canvasRef.current) {
        canvasRef.current.updateSelectedComponent(updates);
        setSelectedComponent(prev => prev ? { ...prev, ...updates } : null);
    }
  };

  return (
    <div className="fixed inset-0 flex bg-slate-50 text-slate-800 font-sans overflow-hidden select-none overscroll-none">
      <input type="file" ref={fileInputRef} onChange={handleFileImport} accept=".json" className="hidden" />
      <Sidebar 
        selectedTool={selectedTool} 
        onSelectTool={(t) => { if (t === 'SELECT' || t === 'DELETE') setSelectedTool(t); }}
        onTouchStartItem={handleTouchStartItem}
        functionLibrary={functions}
      />
      <main className="flex-1 flex flex-col relative overflow-hidden">
        <div 
            className="absolute top-4 left-4 right-4 md:h-14 bg-white/95 backdrop-blur shadow-sm rounded-md flex flex-wrap md:flex-nowrap items-center justify-between px-4 z-10 border border-slate-200 pointer-events-auto py-2 md:py-0 gap-2"
            onPointerDown={(e) => e.stopPropagation()}
            onMouseDown={(e) => e.stopPropagation()}
            onTouchStart={(e) => e.stopPropagation()}
        >
          <div className="flex items-center space-x-2 md:space-x-4">
             <div className="flex items-center bg-slate-100 rounded p-1 border border-slate-200">
               <span className="text-xs font-bold text-slate-400 px-2 hidden sm:inline">FUNC:</span>
               <select 
                 value={activeFunctionId}
                 onChange={(e) => switchToFunction(e.target.value)}
                 className="bg-transparent text-sm font-semibold text-slate-700 outline-none w-24 sm:w-32 cursor-pointer py-1"
               >
                 {functions.map(f => <option key={f.id} value={f.id}>{f.name}</option>)}
               </select>
               <button onClick={openNewFunctionModal} className="ml-2 w-8 h-8 flex items-center justify-center bg-blue-100 text-blue-600 rounded hover:bg-blue-200 text-lg font-bold" title="New Function">+</button>
               {activeFunctionId !== 'main' && (
                 <button onClick={() => deleteFunction(activeFunctionId)} className="ml-1 w-8 h-8 flex items-center justify-center bg-red-100 text-red-500 rounded hover:bg-red-200 text-lg font-bold" title="Delete Function">×</button>
               )}
             </div>
             <div className="h-5 w-px bg-slate-200 hidden sm:block"></div>
             <button onClick={() => setIsPlaying(!isPlaying)} className="px-4 py-2 bg-slate-100 hover:bg-slate-200 rounded text-sm font-semibold text-slate-700 transition-colors">
               {isPlaying ? 'Pause' : 'Resume'}
             </button>
             <div className="relative">
                <button onClick={() => setIsProjectMenuOpen(!isProjectMenuOpen)} className="flex items-center space-x-1 px-3 py-2 bg-slate-50 hover:bg-slate-100 border border-slate-200 rounded text-sm font-semibold text-slate-700 transition-colors">
                    <span>Project</span><span className="text-xs">▼</span>
                </button>
                {isProjectMenuOpen && (
                    <div className="absolute top-full left-0 mt-2 w-64 bg-white rounded-lg shadow-xl border border-slate-100 py-2 z-50 flex flex-col">
                         <div className="px-4 py-2 text-xs text-slate-400 font-mono border-b border-slate-50 mb-1">{lastSaved ? `Saved: ${lastSaved.toLocaleTimeString()}` : 'Not saved yet'}</div>
                        <button onClick={handleQuickSave} className="px-4 py-2 text-left text-sm text-slate-700 hover:bg-slate-50 flex items-center"><span className="mr-2">💾</span> Save Now</button>
                        <button onClick={triggerFileUpload} className="px-4 py-2 text-left text-sm text-slate-700 hover:bg-slate-50 flex items-center"><span className="mr-2">📂</span> Import File...</button>
                        <button onClick={handleExportProject} className="px-4 py-2 text-left text-sm text-slate-700 hover:bg-slate-50 flex items-center"><span className="mr-2">📦</span> Export Project (All)</button>
                        <button onClick={handleExportFunction} className="px-4 py-2 text-left text-sm text-slate-700 hover:bg-slate-50 flex items-center"><span className="mr-2">📄</span> Export Function (Active)</button>
                        <div className="h-px bg-slate-100 my-1"></div>
                        <button onClick={handleClearStorage} className="px-4 py-2 text-left text-sm text-red-600 hover:bg-red-50 flex items-center"><span className="mr-2">🗑️</span> Clear Browser Data</button>
                    </div>
                )}
                {isProjectMenuOpen && <div className="fixed inset-0 z-40" onClick={() => setIsProjectMenuOpen(false)}></div>}
             </div>
          </div>

          <div className="flex items-center space-x-3 w-full md:w-auto justify-end">
             {selectedComponent && (
                 <div className="flex items-center space-x-2 mr-2 flex-1 md:flex-none justify-center">

                     {/* Bit Width Selector */}
                     {/* Allow for Gates, IO, Splitters/Mergers. Hide for Custom IC currently. */}
                     {selectedComponent.type !== ComponentType.CUSTOM_IC && (
                        <div className="flex items-center bg-purple-50 px-2 py-1 rounded border border-purple-200">
                             <span className="text-[10px] font-bold text-purple-600 mr-2 uppercase whitespace-nowrap">Bits</span>
                             <select
                                 value={selectedComponent.bitWidth || 1}
                                 onChange={(e) => updateComponentProp({ bitWidth: Number(e.target.value) })}
                                 className="bg-white border border-purple-200 text-sm px-2 py-1 rounded w-16 focus:outline-none focus:border-purple-400 shadow-sm"
                             >
                                 <option value="1">1</option>
                                 <option value="2">2</option>
                                 <option value="4">4</option>
                                 <option value="8">8</option>
                                 <option value="16">16</option>
                                 <option value="32">32</option>
                                 <option value="64">64</option>
                                 <option value="128">128</option>
                             </select>
                        </div>
                     )}

                     <div className="flex items-center bg-yellow-50 px-2 py-1 rounded border border-yellow-200">
                        <span className="text-[10px] font-bold text-yellow-600 mr-2 uppercase whitespace-nowrap">Label</span>
                        <input type="text" value={tempLabel} onChange={(e) => updateLabel(e.target.value)} className="bg-white border border-yellow-200 text-base px-2 py-1 rounded w-20 focus:outline-none focus:border-yellow-400 shadow-sm" />
                     </div>

                     {(selectedComponent.type === ComponentType.INPUT_SWITCH || selectedComponent.type === ComponentType.OUTPUT_LED || selectedComponent.type === ComponentType.CLOCK) && (
                         <div className="flex items-center bg-blue-50 px-2 py-1 rounded border border-blue-200">
                            <span className="text-[10px] font-bold text-blue-600 mr-2 uppercase whitespace-nowrap">Side</span>
                            <select 
                                value={selectedComponent.icPortSide || (selectedComponent.type === ComponentType.INPUT_SWITCH || selectedComponent.type === ComponentType.CLOCK ? 'right' : 'left')}
                                onChange={(e) => updateComponentProp({ icPortSide: e.target.value as any })}
                                className="bg-white border border-blue-200 text-sm px-2 py-1 rounded w-20 focus:outline-none focus:border-blue-400 shadow-sm"
                            >
                                <option value="top">Top</option>
                                <option value="bottom">Bottom</option>
                                <option value="left">Left</option>
                                <option value="right">Right</option>
                            </select>
                         </div>
                     )}
                 </div>
             )}
            <input type="range" min="5" max="1000" step="5" value={tickSpeed} onChange={(e) => setTickSpeed(Number(e.target.value))} className="w-16 sm:w-24 h-4 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-slate-900" />
          </div>
        </div>
        <div className="flex-1 w-full h-full relative z-0" ref={canvasWrapperRef}>
          <LogicCanvas 
            key={`${activeFunctionId}-${dataVersion}`}
            ref={canvasRef}
            tool={selectedTool} 
            isPlaying={isPlaying} 
            tickSpeedMs={tickSpeed}
            pendingDrop={pendingDrop}
            initialComponents={activeFunction.components}
            initialWires={activeFunction.wires}
            functionLibrary={functions}
            onPendingDropHandled={handlePendingDropHandled}
            onSelectionChange={handleSelectionChange}
          />
        </div>
        {draggedType && dragPos && (
          <div className="fixed pointer-events-none z-50 opacity-80" style={{ left: dragPos.x, top: dragPos.y, transform: 'translate(-50%, -50%)' }}>
            <div className="w-12 h-12 bg-blue-100 border-2 border-blue-500 rounded flex items-center justify-center shadow-xl">
              <span className="text-[10px] font-bold text-blue-800">{draggedType === ComponentType.CUSTOM_IC ? 'IC' : COMPONENT_DEFINITIONS[draggedType].label}</span>
            </div>
          </div>
        )}
        {isModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm overflow-hidden" onPointerDown={(e) => e.stopPropagation()}>
              <div className="bg-slate-50 px-4 py-3 border-b border-slate-100"><h3 className="font-bold text-slate-700">Create New Function</h3></div>
              <form onSubmit={submitNewFunction} className="p-4">
                <label className="block text-xs font-bold text-slate-400 uppercase mb-1">Function Name</label>
                <input autoFocus type="text" value={newFuncName} onChange={(e) => setNewFuncName(e.target.value)} placeholder="e.g. Full Adder" className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 mb-4 text-base font-semibold text-slate-700" />
                <div className="flex justify-end space-x-2">
                  <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-sm font-bold text-slate-500 hover:bg-slate-100 rounded-lg transition-colors">Cancel</button>
                  <button type="submit" className="px-4 py-2 text-sm font-bold text-white bg-blue-600 hover:bg-blue-700 rounded-lg shadow-sm transition-colors">Create</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { ComponentType, FunctionCircuit } from '../types';
import { COMPONENT_DEFINITIONS } from '../constants';

interface SidebarProps {
  selectedTool: 'SELECT' | 'DELETE';
  onSelectTool: (t: 'SELECT' | 'DELETE') => void;
  onTouchStartItem?: (type: ComponentType, e: React.TouchEvent, functionId?: string, bitWidth?: number) => void;
  functionLibrary: FunctionCircuit[];
}

const BIT_WIDTHS = [1, 2, 4, 8, 16, 32, 64, 128];

const Sidebar: React.FC<SidebarProps> = ({ selectedTool, onSelectTool, onTouchStartItem, functionLibrary }) => {
  const [selectedBitWidth, setSelectedBitWidth] = useState<number>(1);

  const groups = [
    { 
      name: 'I/O & Control', 
      items: [ComponentType.INPUT_SWITCH, ComponentType.OUTPUT_LED, ComponentType.CLOCK, ComponentType.HEX_DISPLAY] 
    },
    { 
      name: 'Logic Gates', 
      items: [ComponentType.NOT, ComponentType.AND, ComponentType.OR, ComponentType.NAND, ComponentType.NOR, ComponentType.XOR] 
    },
    { 
      name: 'Bus Routing', 
      items: [ComponentType.SPLITTER, ComponentType.MERGER] 
    }
  ];

  const handleDragStart = (e: React.DragEvent, type: ComponentType, functionId?: string) => {
    // For Custom ICs, we ignore the global bit width selector as they have internal fixed logic
    const bitWidth = type === ComponentType.CUSTOM_IC ? 1 : selectedBitWidth;
    e.dataTransfer.setData('application/react-logic-sim', JSON.stringify({ type, functionId, bitWidth }));
    e.dataTransfer.effectAllowed = 'copy';
  };

  const draggableFunctions = functionLibrary.filter(f => f.id !== 'main');

  return (
    <div className="w-72 bg-slate-50 border-r border-slate-200 flex flex-col h-full shadow-xl z-20 flex-shrink-0 font-sans">
      {/* Header */}
      <div className="p-5 border-b border-slate-200 bg-white">
        <h1 className="text-2xl font-extrabold text-slate-800 tracking-tight flex items-center">
          <span className="bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-indigo-600">
            LogicFlow
          </span>
        </h1>
        <p className="text-xs text-slate-400 mt-1 font-medium">Digital Logic Simulator</p>
      </div>

      {/* Bit Width Tabs */}
      <div className="px-4 pt-4 pb-2 bg-slate-50">
        <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">Bus Width (Bits)</h3>
        <div className="flex flex-wrap gap-1">
          {BIT_WIDTHS.map(width => (
            <button
              key={width}
              onClick={() => setSelectedBitWidth(width)}
              className={`
                flex-1 min-w-[30px] h-8 rounded-md text-xs font-bold transition-all duration-200 border shadow-sm
                ${selectedBitWidth === width 
                  ? 'bg-blue-600 text-white border-blue-600 ring-2 ring-blue-200 ring-offset-1' 
                  : 'bg-white text-slate-600 border-slate-200 hover:border-slate-300 hover:bg-slate-50'
                }
              `}
            >
              {width}
            </button>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-4 py-2 space-y-6 custom-scrollbar">

        {/* Tools Section */}
        <div>
          <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3">Tools</h3>
          <div className="flex gap-2">
            <button
              onClick={() => onSelectTool('SELECT')}
              className={`flex-1 py-2 px-3 rounded-lg text-sm font-bold transition-all duration-200 flex items-center justify-center space-x-2 border shadow-sm ${
                selectedTool === 'SELECT' 
                  ? 'bg-white text-blue-600 border-blue-200 ring-2 ring-blue-100' 
                  : 'bg-slate-100 text-slate-500 border-transparent hover:bg-white hover:border-slate-200'
              }`}
            >
              <span className="text-lg">🖱️</span>
              <span>Select</span>
            </button>
            <button
              onClick={() => onSelectTool('DELETE')}
              className={`flex-1 py-2 px-3 rounded-lg text-sm font-bold transition-all duration-200 flex items-center justify-center space-x-2 border shadow-sm ${
                selectedTool === 'DELETE' 
                  ? 'bg-red-50 text-red-600 border-red-200 ring-2 ring-red-100' 
                  : 'bg-slate-100 text-slate-500 border-transparent hover:bg-white hover:border-slate-200'
              }`}
            >
              <span className="text-lg">🗑️</span>
              <span>Delete</span>
            </button>
          </div>
        </div>

        {/* Component Groups */}
        {groups.map(group => (
          <div key={group.name}>
            <div className="flex items-center justify-between mb-3">
               <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{group.name}</h3>
               <span className="text-[9px] font-semibold text-blue-500 bg-blue-50 px-1.5 py-0.5 rounded border border-blue-100">
                 {selectedBitWidth} BIT
               </span>
            </div>
            <div className="grid grid-cols-2 gap-3">
              {group.items.map(type => {
                const def = COMPONENT_DEFINITIONS[type];
                // Styling logic based on type
                let iconColor = "text-slate-600";
                let borderColor = "border-slate-200";
                let bgColor = "bg-white";

                if (['AND', 'NAND'].includes(type)) { iconColor = "text-emerald-600"; borderColor="group-hover:border-emerald-300"; }
                if (['OR', 'NOR'].includes(type)) { iconColor = "text-amber-600"; borderColor="group-hover:border-amber-300"; }
                if (['XOR', 'NOT'].includes(type)) { iconColor = "text-purple-600"; borderColor="group-hover:border-purple-300"; }
                if (['INPUT', 'OUTPUT', 'HEX'].includes(type)) { iconColor = "text-blue-600"; borderColor="group-hover:border-blue-300"; }

                return (
                  <div
                    key={type}
                    draggable={true}
                    onDragStart={(e) => handleDragStart(e, type)}
                    onTouchStart={(e) => onTouchStartItem && onTouchStartItem(type, e, undefined, selectedBitWidth)}
                    className={`
                      group relative flex flex-col items-center justify-center p-3 rounded-xl border-2 transition-all duration-200 cursor-grab active:cursor-grabbing touch-none select-none shadow-sm hover:shadow-md
                      ${bgColor} ${borderColor}
                    `}
                  >
                    <div className={`w-10 h-10 mb-2 rounded-lg bg-slate-50 border border-slate-100 flex items-center justify-center ${iconColor} font-bold text-xs shadow-inner`}>
                      {def.label.substring(0,4)}
                    </div>
                    <span className="text-xs font-bold text-slate-600 group-hover:text-slate-800">{def.label}</span>

                    {/* Bit width badge on hover/always */}
                    <div className="absolute top-1 right-1 opacity-0 group-hover:opacity-100 transition-opacity bg-slate-800 text-white text-[8px] font-bold px-1 rounded">
                      {selectedBitWidth}b
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        ))}

        {/* Custom Functions */}
        {draggableFunctions.length > 0 && (
            <div>
                 <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3">Custom ICs</h3>
                 <div className="flex flex-col gap-2">
                    {draggableFunctions.map(func => (
                        <div
                            key={func.id}
                            draggable={true}
                            onDragStart={(e) => handleDragStart(e, ComponentType.CUSTOM_IC, func.id)}
                            onTouchStart={(e) => onTouchStartItem && onTouchStartItem(ComponentType.CUSTOM_IC, e, func.id, 1)}
                            className="flex items-center p-3 rounded-lg border border-indigo-100 bg-indigo-50/50 hover:bg-white hover:border-indigo-300 hover:shadow-md transition-all duration-200 cursor-grab active:cursor-grabbing touch-none"
                        >
                             <div className="w-8 h-8 mr-3 rounded-md bg-white border border-indigo-200 flex items-center justify-center text-[10px] font-bold text-indigo-600 shadow-sm pointer-events-none">
                                IC
                             </div>
                             <span className="text-sm font-bold text-slate-700 pointer-events-none truncate">{func.name}</span>
                        </div>
                    ))}
                 </div>
            </div>
        )}

      </div>
    </div>
  );
};

export default Sidebar;

import React, { useState, useRef, useEffect, useLayoutEffect } from 'react';
import Sidebar from './components/Sidebar';
import LogicCanvas, { LogicCanvasHandle } from './components/LogicCanvas';
import { ComponentType, CircuitComponent, Wire, FunctionCircuit } from './types';
import { COMPONENT_DEFINITIONS } from './constants';

const LOCAL_STORAGE_KEY = 'logicflow_autosave_v1';
const LOCAL_STORAGE_ID_KEY = 'logicflow_active_id_v1';

const App: React.FC = () => {
  const [selectedTool, setSelectedTool] = useState<'SELECT' | 'DELETE'>('SELECT');
  const [isPlaying, setIsPlaying] = useState(false); 
  const [tickSpeed, setTickSpeed] = useState(50); 

  const [functions, setFunctions] = useState<FunctionCircuit[]>(() => {
    try {
      const saved = localStorage.getItem(LOCAL_STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed) && parsed.length > 0) {
          return parsed;
        }
      }
    } catch (e) {
      console.error("Failed to load autosave", e);
    }
    return [{ id: 'main', name: 'Main Circuit', components: [], wires: [] }];
  });

  const [activeFunctionId, setActiveFunctionId] = useState<string>(() => {
    try {
        const savedId = localStorage.getItem(LOCAL_STORAGE_ID_KEY);
        if (savedId) return savedId;
    } catch(e) {}
    return 'main';
  });

  useLayoutEffect(() => {
    if (!functions.find(f => f.id === activeFunctionId)) {
        setActiveFunctionId(functions[0]?.id || 'main');
    }
  }, [functions, activeFunctionId]);

  const [dataVersion, setDataVersion] = useState(0);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newFuncName, setNewFuncName] = useState("");
  const [isProjectMenuOpen, setIsProjectMenuOpen] = useState(false);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);

  const [selectedComponent, setSelectedComponent] = useState<CircuitComponent | null>(null);
  const [tempLabel, setTempLabel] = useState("");

  const [draggedType, setDraggedType] = useState<ComponentType | null>(null);
  const [draggedFuncId, setDraggedFuncId] = useState<string | undefined>(undefined);
  const [draggedBitWidth, setDraggedBitWidth] = useState<number>(1); // Store dragged bit width
  const [dragPos, setDragPos] = useState<{x: number, y: number} | null>(null);
  const [pendingDrop, setPendingDrop] = useState<{type: ComponentType, x: number, y: number, functionId?: string, bitWidth?: number} | null>(null);

  const canvasWrapperRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<LogicCanvasHandle>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const functionsRef = useRef(functions);
  const activeIdRef = useRef(activeFunctionId);

  useEffect(() => { functionsRef.current = functions; }, [functions]);
  useEffect(() => { activeIdRef.current = activeFunctionId; }, [activeFunctionId]);

  const activeFunction = functions.find(f => f.id === activeFunctionId) || functions[0];

  const persistToStorage = () => {
    let currentData = functionsRef.current;
    if (canvasRef.current) {
        const { components, wires } = canvasRef.current.getData();
        const activeId = activeIdRef.current;
        currentData = currentData.map(f => 
            f.id === activeId 
              ? { ...f, components: [...components], wires: [...wires] } 
              : f
        );
    }
    try {
        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(currentData));
        localStorage.setItem(LOCAL_STORAGE_ID_KEY, activeIdRef.current);
        setLastSaved(new Date());
    } catch (e) {
        console.error("Autosave failed", e);
    }
  };

  useEffect(() => {
    const interval = setInterval(persistToStorage, 5000);
    const handleVisibilityChange = () => { if (document.hidden) persistToStorage(); };
    document.addEventListener("visibilitychange", handleVisibilityChange);
    const handleBeforeUnload = () => { persistToStorage(); };
    window.addEventListener("beforeunload", handleBeforeUnload);

    return () => {
        clearInterval(interval);
        document.removeEventListener("visibilitychange", handleVisibilityChange);
        window.removeEventListener("beforeunload", handleBeforeUnload);
        persistToStorage();
    };
  }, []);

  const handleTouchStartItem = (type: ComponentType, e: React.TouchEvent, functionId?: string, bitWidth: number = 1) => {
    const touch = e.touches[0];
    setDraggedType(type);
    setDraggedFuncId(functionId);
    setDraggedBitWidth(bitWidth);
    setDragPos({ x: touch.clientX, y: touch.clientY });
  };

  useEffect(() => {
    const handleTouchMove = (e: TouchEvent) => {
      if (draggedType) {
        e.preventDefault(); 
        const touch = e.touches[0];
        setDragPos({ x: touch.clientX, y: touch.clientY });
      }
    };

    const handleTouchEnd = (e: TouchEvent) => {
      if (draggedType && dragPos && canvasWrapperRef.current) {
        const rect = canvasWrapperRef.current.getBoundingClientRect();
        if (
          dragPos.x >= rect.left &&
          dragPos.x <= rect.right &&
          dragPos.y >= rect.top &&
          dragPos.y <= rect.bottom
        ) {
          const relX = dragPos.x - rect.left;
          const relY = dragPos.y - rect.top;
          setPendingDrop({ type: draggedType, x: relX, y: relY, functionId: draggedFuncId, bitWidth: draggedBitWidth });
        }
      }
      setDraggedType(null);
      setDraggedFuncId(undefined);
      setDragPos(null);
    };

    if (draggedType) {
      window.addEventListener('touchmove', handleTouchMove, { passive: false });
      window.addEventListener('touchend', handleTouchEnd);
    }

    return () => {
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
    };
  }, [draggedType, dragPos, draggedFuncId, draggedBitWidth]);

  const handlePendingDropHandled = () => {
    setPendingDrop(null);
  };

  const getLatestFunctionsState = (): FunctionCircuit[] => {
    if (canvasRef.current) {
      const { components, wires } = canvasRef.current.getData();
      return functions.map(f => 
        f.id === activeFunctionId 
          ? { ...f, components: [...components], wires: [...wires] }
          : f
      );
    }
    return functions;
  };

  const saveCurrentState = () => {
    const updated = getLatestFunctionsState();
    setFunctions(updated);
    try {
        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(updated));
        localStorage.setItem(LOCAL_STORAGE_ID_KEY, activeFunctionId);
        setLastSaved(new Date());
    } catch(e) {}
    return updated;
  };

  const switchToFunction = (id: string) => {
    if (id === activeFunctionId) return;
    saveCurrentState();
    setSelectedComponent(null);
    setActiveFunctionId(id);
    setIsPlaying(false);
  };

  const handleQuickSave = () => {
    persistToStorage();
    setIsProjectMenuOpen(false);
  };

  const handleClearStorage = () => {
    if (confirm("Clear local saved data? This will reset the project.")) {
        localStorage.removeItem(LOCAL_STORAGE_KEY);
        localStorage.removeItem(LOCAL_STORAGE_ID_KEY);
        const defaultState = [{ id: 'main', name: 'Main Circuit', components: [], wires: [] }];
        setFunctions(defaultState);
        setActiveFunctionId('main');
        setDataVersion(v => v + 1);
    }
    setIsProjectMenuOpen(false);
  };

  const downloadJSON = (data: any, filename: string) => {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleExportProject = () => {
    const data = getLatestFunctionsState();
    downloadJSON(data, `logicflow_project_${new Date().getTime()}.json`);
    setIsProjectMenuOpen(false);
  };

  const handleExportFunction = () => {
    if (canvasRef.current) {
        const { components, wires } = canvasRef.current.getData();
        const funcData: FunctionCircuit = {
            ...activeFunction,
            components,
            wires
        };
        downloadJSON(funcData, `${activeFunction.name.replace(/\s+/g, '_')}_function.json`);
    }
    setIsProjectMenuOpen(false);
  };

  const triggerFileUpload = () => {
    fileInputRef.current?.click();
    setIsProjectMenuOpen(false);
  };

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const content = e.target?.result as string;
            const parsed = JSON.parse(content);

            if (Array.isArray(parsed)) {
                if (parsed.length > 0 && parsed[0].id && parsed[0].components) {
                    if (confirm("This will replace your current project. Continue?")) {
                        setFunctions(parsed);
                        setActiveFunctionId(parsed[0].id);
                        setSelectedComponent(null);
                        setIsPlaying(false);
                        setDataVersion(v => v + 1);
                        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(parsed));
                        localStorage.setItem(LOCAL_STORAGE_ID_KEY, parsed[0].id);
                    }
                } else {
                    alert("Invalid Project File");
                }
            } else if (typeof parsed === 'object' && parsed.id && parsed.components) {
                const newFunc = parsed as FunctionCircuit;
                const existing = functions.find(f => f.id === newFunc.id);
                if (existing) {
                    newFunc.id = crypto.randomUUID();
                    newFunc.name = `${newFunc.name} (Imported)`;
                }
                const currentData = getLatestFunctionsState();
                const newData = [...currentData, newFunc];
                setFunctions(newData);
                localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(newData));
                alert(`Imported function: ${newFunc.name}`);
            } else {
                alert("Unknown file format.");
            }
        } catch (err) {
            console.error(err);
            alert("Failed to parse JSON file.");
        }
        if (fileInputRef.current) fileInputRef.current.value = "";
    };
    reader.readAsText(file);
  };

  const openNewFunctionModal = () => {
    setNewFuncName("");
    setIsModalOpen(true);
  };

  const submitNewFunction = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newFuncName.trim()) return;
    const currentData = saveCurrentState(); 
    const newId = crypto.randomUUID();
    const newFunc: FunctionCircuit = {
      id: newId,
      name: newFuncName,
      components: [],
      wires: []
    };
    const nextState = [...currentData, newFunc];
    setFunctions(nextState);
    setActiveFunctionId(newId);
    setIsModalOpen(false);
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(nextState));
    localStorage.setItem(LOCAL_STORAGE_ID_KEY, newId);
  };

  const deleteFunction = (id: string) => {
    if (id === 'main') {
      alert("Cannot delete Main Circuit");
      return;
    }
    if (confirm("Are you sure you want to delete this function?")) {
      const nextState = functions.filter(f => f.id !== id);
      setFunctions(nextState);
      localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(nextState));
      if (activeFunctionId === id) {
        setActiveFunctionId('main');
        localStorage.setItem(LOCAL_STORAGE_ID_KEY, 'main');
      }
    }
  };

  const handleSelectionChange = (comp: CircuitComponent | null) => {
      setSelectedComponent(comp);
      if (comp) {
          setTempLabel(comp.customLabel || (comp.type === ComponentType.INPUT_SWITCH ? "IN" : (comp.type === ComponentType.OUTPUT_LED ? "OUT" : "")));
      } else {
        setTempLabel("");
      }
  };

  const updateLabel = (val: string) => {
      setTempLabel(val);
      updateComponentProp({ customLabel: val });
  };

  const updateComponentProp = (updates: Partial<CircuitComponent>) => {
    if (selectedComponent && canvasRef.current) {
        canvasRef.current.updateSelectedComponent(updates);
        setSelectedComponent(prev => prev ? { ...prev, ...updates } : null);
    }
  };

  return (
    <div className="fixed inset-0 flex bg-slate-50 text-slate-800 font-sans overflow-hidden select-none overscroll-none">
      <input type="file" ref={fileInputRef} onChange={handleFileImport} accept=".json" className="hidden" />
      <Sidebar 
        selectedTool={selectedTool} 
