             <div className="relative">
                <button onClick={() => setIsProjectMenuOpen(!isProjectMenuOpen)} className="flex items-center space-x-1 px-3 py-2 bg-slate-50 hover:bg-slate-100 border border-slate-200 rounded text-sm font-semibold text-slate-700 transition-colors">
                    <span>Project</span><span className="text-xs">▼</span>
                </button>
                {isProjectMenuOpen && (
                    <div className="absolute top-full left-0 mt-2 w-64 bg-white rounded-lg shadow-xl border border-slate-100 py-2 z-50 flex flex-col">
                         <div className="px-4 py-2 text-xs text-slate-400 font-mono border-b border-slate-50 mb-1">{lastSaved ? `Saved: ${lastSaved.toLocaleTimeString()}` : 'Not saved yet'}</div>
                        <button onClick={handleQuickSave} className="px-4 py-2 text-left text-sm text-slate-700 hover:bg-slate-50 flex items-center"><span className="mr-2">💾</span> Save Now</button>
                        <button onClick={triggerFileUpload} className="px-4 py-2 text-left text-sm text-slate-700 hover:bg-slate-50 flex items-center"><span className="mr-2">📂</span> Import File...</button>
                        <button onClick={handleExportProject} className="px-4 py-2 text-left text-sm text-slate-700 hover:bg-slate-50 flex items-center"><span className="mr-2">📦</span> Export Project (All)</button>
                        <button onClick={handleExportFunction} className="px-4 py-2 text-left text-sm text-slate-700 hover:bg-slate-50 flex items-center"><span className="mr-2">📄</span> Export Function (Active)</button>
                        <div className="h-px bg-slate-100 my-1"></div>
                        <button onClick={handleClearStorage} className="px-4 py-2 text-left text-sm text-red-600 hover:bg-red-50 flex items-center"><span className="mr-2">🗑️</span> Clear Browser Data</button>
                    </div>
                )}
                {isProjectMenuOpen && <div className="fixed inset-0 z-40" onClick={() => setIsProjectMenuOpen(false)}></div>}
             </div>
          </div>

          <div className="flex items-center space-x-3 w-full md:w-auto justify-end">
             {selectedComponent && (
                 <div className="flex items-center space-x-2 mr-2 flex-1 md:flex-none justify-center">

                     {/* Bit Width Selector */}
                     {/* Allow for Gates, IO, Splitters/Mergers. Hide for Custom IC currently. */}
                     {selectedComponent.type !== ComponentType.CUSTOM_IC && (
                        <div className="flex items-center bg-purple-50 px-2 py-1 rounded border border-purple-200">
                             <span className="text-[10px] font-bold text-purple-600 mr-2 uppercase whitespace-nowrap">Bits</span>
                             <select
                                 value={selectedComponent.bitWidth || 1}
                                 onChange={(e) => updateComponentProp({ bitWidth: Number(e.target.value) })}
                                 className="bg-white border border-purple-200 text-sm px-2 py-1 rounded w-16 focus:outline-none focus:border-purple-400 shadow-sm"
                             >
                                 <option value="1">1</option>
                                 <option value="2">2</option>
                                 <option value="4">4</option>
                                 <option value="8">8</option>
                                 <option value="16">16</option>
                                 <option value="32">32</option>
                                 <option value="64">64</option>
                                 <option value="128">128</option>
                             </select>
                        </div>
                     )}

                     <div className="flex items-center bg-yellow-50 px-2 py-1 rounded border border-yellow-200">
                        <span className="text-[10px] font-bold text-yellow-600 mr-2 uppercase whitespace-nowrap">Label</span>
                        <input type="text" value={tempLabel} onChange={(e) => updateLabel(e.target.value)} className="bg-white border border-yellow-200 text-base px-2 py-1 rounded w-20 focus:outline-none focus:border-yellow-400 shadow-sm" />
                     </div>

                     {(selectedComponent.type === ComponentType.INPUT_SWITCH || selectedComponent.type === ComponentType.OUTPUT_LED || selectedComponent.type === ComponentType.CLOCK) && (
                         <div className="flex items-center bg-blue-50 px-2 py-1 rounded border border-blue-200">
                            <span className="text-[10px] font-bold text-blue-600 mr-2 uppercase whitespace-nowrap">Side</span>
                            <select 
                                value={selectedComponent.icPortSide || (selectedComponent.type === ComponentType.INPUT_SWITCH || selectedComponent.type === ComponentType.CLOCK ? 'right' : 'left')}
                                onChange={(e) => updateComponentProp({ icPortSide: e.target.value as any })}
                                className="bg-white border border-blue-200 text-sm px-2 py-1 rounded w-20 focus:outline-none focus:border-blue-400 shadow-sm"
                            >
                                <option value="top">Top</option>
                                <option value="bottom">Bottom</option>
                                <option value="left">Left</option>
                                <option value="right">Right</option>
                            </select>
                         </div>
                     )}
                 </div>
             )}
            <input type="range" min="5" max="1000" step="5" value={tickSpeed} onChange={(e) => setTickSpeed(Number(e.target.value))} className="w-16 sm:w-24 h-4 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-slate-900" />
          </div>
        </div>
        <div className="flex-1 w-full h-full relative z-0" ref={canvasWrapperRef}>
          <LogicCanvas 
            key={`${activeFunctionId}-${dataVersion}`}
            ref={canvasRef}
            tool={selectedTool} 
            isPlaying={isPlaying} 
            tickSpeedMs={tickSpeed}
            pendingDrop={pendingDrop}
            initialComponents={activeFunction.components}
            initialWires={activeFunction.wires}
            functionLibrary={functions}
            onPendingDropHandled={handlePendingDropHandled}
            onSelectionChange={handleSelectionChange}
          />
        </div>
        {draggedType && dragPos && (
          <div className="fixed pointer-events-none z-50 opacity-90" style={{ left: dragPos.x, top: dragPos.y, transform: 'translate(-50%, -50%)' }}>
            <div className="w-14 h-14 bg-white border-2 border-blue-500 rounded-xl flex flex-col items-center justify-center shadow-2xl">
              <span className="text-[10px] font-bold text-blue-800">{draggedType === ComponentType.CUSTOM_IC ? 'IC' : COMPONENT_DEFINITIONS[draggedType].label.substring(0,4)}</span>
              {draggedBitWidth > 1 && <span className="text-[8px] bg-blue-100 px-1 rounded text-blue-800 font-bold mt-1">{draggedBitWidth}b</span>}
            </div>
          </div>
        )}
        {isModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm overflow-hidden" onPointerDown={(e) => e.stopPropagation()}>
              <div className="bg-slate-50 px-4 py-3 border-b border-slate-100"><h3 className="font-bold text-slate-700">Create New Function</h3></div>
              <form onSubmit={submitNewFunction} className="p-4">
                <label className="block text-xs font-bold text-slate-400 uppercase mb-1">Function Name</label>
                <input autoFocus type="text" value={newFuncName} onChange={(e) => setNewFuncName(e.target.value)} placeholder="e.g. Full Adder" className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 mb-4 text-base font-semibold text-slate-700" />
                <div className="flex justify-end space-x-2">
                  <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-sm font-bold text-slate-500 hover:bg-slate-100 rounded-lg transition-colors">Cancel</button>
                  <button type="submit" className="px-4 py-2 text-sm font-bold text-white bg-blue-600 hover:bg-blue-700 rounded-lg shadow-sm transition-colors">Create</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useImperativeHandle, forwardRef } from 'react';
import p5Types from 'p5'; // Just for types
import { ComponentType, CircuitComponent, Wire, Point, FunctionCircuit, PortSide } from '../types';
import { COMPONENT_DEFINITIONS, GRID_SIZE, COLOR_BG, COLOR_COMPONENT_BG, COLOR_COMPONENT_STROKE, COLOR_GRID, COLOR_WIRE_OFF, COLOR_WIRE_ON, COLOR_BUS_OFF, COLOR_BUS_ON } from '../constants';
import { stepSimulation } from '../logic/circuitEngine';

// Extend Window interface to allow global p5 usage if needed
declare global {
  interface Window {
    p5: any;
  }
}

export interface LogicCanvasHandle {
  getData: () => { components: CircuitComponent[], wires: Wire[] };
  updateSelectedComponent: (updates: Partial<CircuitComponent>) => void;
  deleteSelected: () => void;
}

interface LogicCanvasProps {
  tool: 'SELECT' | 'DELETE';
  isPlaying: boolean;
  tickSpeedMs: number; 
  pendingDrop?: { type: ComponentType, x: number, y: number, functionId?: string, bitWidth?: number } | null;
  initialComponents: CircuitComponent[];
  initialWires: Wire[];
  functionLibrary: FunctionCircuit[];
  onPendingDropHandled?: () => void;
  onSelectionChange?: (component: CircuitComponent | null) => void;
}

interface ViewportState {
  x: number;
  y: number;
  zoom: number;
}

type PortPoint = { x: number, y: number, side: 'top' | 'bottom' | 'left' | 'right' };

// Helpers for Sorting / Layout
const getSide = (c: CircuitComponent, isInput: boolean): PortSide => {
    const componentSide = c.icPortSide || (isInput ? 'right' : 'left');
    switch (componentSide) {
        case 'top': return 'bottom';
        case 'bottom': return 'top';
        case 'left': return 'right';
        case 'right': return 'left';
    }
    return 'left';
};
const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };
const sortComponents = (components: CircuitComponent[], isInput: boolean) => {
    return components.sort((a, b) => {
        const sideA = getSide(a, isInput);
        const sideB = getSide(b, isInput);
        if (sideOrder[sideA] !== sideOrder[sideB]) return sideOrder[sideA] - sideOrder[sideB];
        if (sideA === 'top' || sideA === 'bottom') return a.x - b.x;
        return a.y - b.y;
    });
};

const LogicCanvas = forwardRef<LogicCanvasHandle, LogicCanvasProps>(({ 
  tool, 
  isPlaying, 
  tickSpeedMs, 
  pendingDrop, 
  initialComponents,
  initialWires,
  functionLibrary,
  onPendingDropHandled,
  onSelectionChange
}, ref) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const p5InstanceRef = useRef<p5Types | null>(null);

  // -- Simulation State --
  // Ensure we migrate any old boolean values to numbers if loading old save
  const migrateComponents = (comps: any[]) => comps.map(c => ({
      ...c,
      bitWidth: c.bitWidth || 1, // Default 1
      inputValues: c.inputValues.map((v: any) => typeof v === 'boolean' ? (v ? 1 : 0) : v),
      outputValues: c.outputValues.map((v: any) => typeof v === 'boolean' ? (v ? 1 : 0) : v),
  }));

  const componentsRef = useRef<CircuitComponent[]>(migrateComponents(JSON.parse(JSON.stringify(initialComponents))));
  const wiresRef = useRef<Wire[]>(JSON.parse(JSON.stringify(initialWires)));

  // -- Selection & Interaction State --
  const selectedCompId = useRef<string | null>(null); 
  const activeDragId = useRef<string | null>(null);   

  useImperativeHandle(ref, () => ({
    getData: () => ({
        components: componentsRef.current,
        wires: wiresRef.current
    }),
    updateSelectedComponent: (updates: Partial<CircuitComponent>) => {
        if (selectedCompId.current) {
            const comp = componentsRef.current.find(c => c.id === selectedCompId.current);
            if (comp) {
                // If changing bitWidth, we might need to reset connections or resize arrays
                const oldWidth = comp.bitWidth;
                Object.assign(comp, updates);

                if (updates.bitWidth && updates.bitWidth !== oldWidth) {
                    // Reset IO arrays to 0
                    comp.inputValues = new Array(comp.inputValues.length).fill(0);
                    comp.outputValues = new Array(comp.outputValues.length).fill(0);
                }
            }
        }
    },
    deleteSelected: () => {
        if (selectedCompId.current) {
             const id = selectedCompId.current;
             componentsRef.current = componentsRef.current.filter(c => c.id !== id);
             wiresRef.current = wiresRef.current.filter(w => w.fromCompId !== id && w.toCompId !== id);
             selectedCompId.current = null;
             activeDragId.current = null;
             if(onSelectionChange) onSelectionChange(null);
        }
    }
  }));

  // -- Refs for Props --
  const tickSpeedRef = useRef(tickSpeedMs);
  const isPlayingRef = useRef(isPlaying);
  const toolRef = useRef(tool);
  const libraryRef = useRef(functionLibrary);

  useEffect(() => { tickSpeedRef.current = tickSpeedMs; }, [tickSpeedMs]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { toolRef.current = tool; }, [tool]);
  useEffect(() => { libraryRef.current = functionLibrary; }, [functionLibrary]);

  const viewportRef = useRef<ViewportState>({ x: 0, y: 0, zoom: 1.0 });
  const isPanningRef = useRef<boolean>(false);

  const isDraggingComp = useRef<boolean>(false);
  const wiringStart = useRef<{ compId: string, portIndex: number, type: 'input'|'output' } | null>(null);
  const dragOffset = useRef<Point>({ x: 0, y: 0 }); 

  const accumulatorRef = useRef<number>(0);

  const screenToWorld = (sx: number, sy: number): Point => {
    return {
      x: (sx - viewportRef.current.x) / viewportRef.current.zoom,
      y: (sy - viewportRef.current.y) / viewportRef.current.zoom
    };
  };

  const addComponent = (type: ComponentType, screenX: number, screenY: number, functionId?: string, initialBitWidth: number = 1) => {
    const worldPos = screenToWorld(screenX, screenY);
    let def = COMPONENT_DEFINITIONS[type];

    let inputsCount = def.inputs;
    let outputsCount = def.outputs;
    let internalState = undefined;
    let label = def.label;

    // Default Bit Width logic
    let width = initialBitWidth;

    if (type === ComponentType.CUSTOM_IC && functionId) {
        // Custom ICs ignore the requested bit width for now as they are structural
        width = 1; 
        const func = libraryRef.current.find(f => f.id === functionId);
        if (func) {
            inputsCount = func.components.filter(c => c.type === ComponentType.INPUT_SWITCH).length;
            outputsCount = func.components.filter(c => c.type === ComponentType.OUTPUT_LED).length;
            label = func.name;
            internalState = {
                components: JSON.parse(JSON.stringify(func.components)),
                wires: JSON.parse(JSON.stringify(func.wires))
            };
        }
    } else if (type === ComponentType.SPLITTER) {
        // Splitter takes the width and splits into that many bits
        inputsCount = 1;
        outputsCount = width;
    } else if (type === ComponentType.MERGER) {
        // Merger takes that many bits and makes 1 width
        inputsCount = width;
        outputsCount = 1;
    }

    const snapX = Math.round(worldPos.x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(worldPos.y / GRID_SIZE) * GRID_SIZE;

    const newComp: CircuitComponent = {
      id: crypto.randomUUID(),
      type: type,
      x: snapX,
      y: snapY,
      inputValues: new Array(inputsCount).fill(0),
      outputValues: new Array(outputsCount).fill(0),
      bitWidth: width,
      functionId: functionId,
      internalState: internalState,
      customLabel: type === ComponentType.CUSTOM_IC ? label : undefined
    };

    componentsRef.current.push(newComp);
    selectedCompId.current = newComp.id;
    if (onSelectionChange) onSelectionChange(newComp);
  };

  useEffect(() => {
    if (pendingDrop) {
      addComponent(pendingDrop.type, pendingDrop.x, pendingDrop.y, pendingDrop.functionId, pendingDrop.bitWidth);
      if (onPendingDropHandled) onPendingDropHandled();
    }
  }, [pendingDrop, onPendingDropHandled]);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'copy';
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    try {
        const data = e.dataTransfer.getData('application/react-logic-sim');
        if (data) {
            const parsed = JSON.parse(data);
            const { type, functionId, bitWidth } = parsed;

            if (containerRef.current) {
                const rect = containerRef.current.getBoundingClientRect();
                const x = e.clientX - rect.left;
                const y = e.clientY - rect.top;
                addComponent(type, x, y, functionId, bitWidth);
            }
        }
    } catch(err) {
        console.error("Drop failed", err);
    }
  };

  useEffect(() => {
    if (!containerRef.current) return;

    const p5Constructor = (window as any).p5;
    if (!p5Constructor) return;

    if (p5InstanceRef.current) {
        p5InstanceRef.current.remove();
    }

    const sketch = (p: p5Types) => {
      let pinchDistStart = 0;
      let lastTouchX = 0;
      let lastTouchY = 0;
      let isCanvasInteraction = false;

      p.setup = () => {
        p.createCanvas(containerRef.current!.clientWidth, containerRef.current!.clientHeight);
        p.frameRate(60);
        p.textSize(10);
        p.textAlign(p.CENTER, p.CENTER);
        document.oncontextmenu = () => false; 
      };

      (p as any).windowResized = () => {
        if(containerRef.current) {
          p.resizeCanvas(containerRef.current.clientWidth, containerRef.current.clientHeight);
        }
      };

      p.draw = () => {
        p.background(COLOR_BG);

        if (isPlayingRef.current) {
          accumulatorRef.current += p.deltaTime;
          if (accumulatorRef.current > 500) accumulatorRef.current = 500;

          const speed = tickSpeedRef.current;
          while (accumulatorRef.current >= speed) {
            const result = stepSimulation(componentsRef.current, wiresRef.current, libraryRef.current);
            componentsRef.current = result.components;
            wiresRef.current = result.wires;
            accumulatorRef.current -= speed;
          }
        } else {
          accumulatorRef.current = 0;
        }

        p.push();
        p.translate(viewportRef.current.x, viewportRef.current.y);
        p.scale(viewportRef.current.zoom);

        // Grid
        const visibleL = -viewportRef.current.x / viewportRef.current.zoom;
        const visibleT = -viewportRef.current.y / viewportRef.current.zoom;
        const visibleR = (p.width - viewportRef.current.x) / viewportRef.current.zoom;
        const visibleB = (p.height - viewportRef.current.y) / viewportRef.current.zoom;

        const startX = Math.floor(visibleL / GRID_SIZE) * GRID_SIZE;
        const endX = Math.ceil(visibleR / GRID_SIZE) * GRID_SIZE;
        const startY = Math.floor(visibleT / GRID_SIZE) * GRID_SIZE;
        const endY = Math.ceil(visibleB / GRID_SIZE) * GRID_SIZE;

        p.stroke(COLOR_GRID);
        p.strokeWeight(1 / viewportRef.current.zoom); 

        for (let x = startX; x <= endX; x += GRID_SIZE) p.line(x, visibleT, x, visibleB);
        for (let y = startY; y <= endY; y += GRID_SIZE) p.line(visibleL, y, visibleR, y);

        // Wires
        wiresRef.current.forEach(wire => {
          const fromComp = componentsRef.current.find(c => c.id === wire.fromCompId);
          const toComp = componentsRef.current.find(c => c.id === wire.toCompId);
          if (fromComp && toComp) {
            const start = getPortPosition(fromComp, wire.fromPortIndex, 'output');
            const end = getPortPosition(toComp, wire.toPortIndex, 'input');

            // Determine visual style based on component bit width
            // If the source is multi-bit, the wire is multi-bit
            const isBus = fromComp.bitWidth > 1 && fromComp.type !== ComponentType.SPLITTER;
            // Exception: Splitter outputs are single bit

            let color = wire.value > 0 ? COLOR_WIRE_ON : COLOR_WIRE_OFF;
            let weight = 2;

            if (isBus) {
                color = wire.value > 0 ? COLOR_BUS_ON : COLOR_BUS_OFF;
                weight = 4;
            }

            p.stroke(color);
            p.strokeWeight(weight);
            p.noFill();

            const cpOffset = GRID_SIZE * 0.5;
            const cp1 = getWireControlPoint(start, cpOffset);
            const cp2 = getWireControlPoint(end, cpOffset);

            p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, end.x, end.y);

            // Draw value on hover for buses
            // (Simplified: just if selected or debug)
          }
        });

        // Temp Wire
        if (wiringStart.current) {
          const comp = componentsRef.current.find(c => c.id === wiringStart.current!.compId);
          if (comp) {
            const start = getPortPosition(comp, wiringStart.current.portIndex, wiringStart.current.type);
            const mouseWorld = screenToWorld(p.mouseX, p.mouseY);

            // Guess wire style based on source
            const isBus = comp.bitWidth > 1 && !(comp.type === ComponentType.SPLITTER && wiringStart.current.type === 'output') && !(comp.type === ComponentType.MERGER && wiringStart.current.type === 'input');

            p.stroke(isBus ? COLOR_BUS_OFF : COLOR_WIRE_OFF);
            p.strokeWeight(isBus ? 4 : 2);
            p.noFill();

            const cpOffset = GRID_SIZE * 0.5;
            const cp1 = getWireControlPoint(start, cpOffset);
            let cp2 = { x: mouseWorld.x, y: mouseWorld.y };

            // Adaptive bezier
            if (wiringStart.current.type === 'output') cp2 = { x: mouseWorld.x - cpOffset, y: mouseWorld.y };
            else cp2 = { x: mouseWorld.x + cpOffset, y: mouseWorld.y };

            p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, mouseWorld.x, mouseWorld.y);
          }
        }

        // Components
        componentsRef.current.forEach(comp => {
          drawComponent(p, comp);
        });

        // Selection Highlight
        if (selectedCompId.current) {
            const comp = componentsRef.current.find(c => c.id === selectedCompId.current);
            if (comp) {
                const dims = getComponentDimensions(comp);
                p.noFill();
                p.stroke('#3b82f6');
                p.strokeWeight(2);
                const pad = 4;
                p.rect(comp.x - pad, comp.y - pad, (dims.w * GRID_SIZE) + (pad*2), (dims.h * GRID_SIZE) + (pad*2), 4);
            }
        }

        // Hover Highlights
        if (!wiringStart.current && !activeDragId.current) {
            const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
            const hPort = getHoveredPort(mouseWorld.x, mouseWorld.y);
            if (hPort) {
                const comp = componentsRef.current.find(c => c.id === hPort.compId);
                if (comp) {
                    const pos = getPortPosition(comp, hPort.portIndex, hPort.type);
                    p.noFill();
                    p.stroke('#3b82f6');
                    p.strokeWeight(2);
                    p.circle(pos.x, pos.y, 14);
                }
            }
        }

        p.pop();
      };

      const getWireControlPoint = (pt: PortPoint, offset: number) => {
        if (pt.side === 'top') return { x: pt.x, y: pt.y - offset };
        if (pt.side === 'bottom') return { x: pt.x, y: pt.y + offset };
        if (pt.side === 'left') return { x: pt.x - offset, y: pt.y };
        return { x: pt.x + offset, y: pt.y };
      };

      const getComponentDimensions = (comp: CircuitComponent) => {
          if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
             const funcDef = libraryRef.current.find(f => f.id === comp.functionId);
             if (funcDef) {
                const inputs = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH);
                const outputs = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);
                const width = Math.max(2, Math.max(
                    inputs.filter(c => getSide(c, true) === 'top').length + outputs.filter(c => getSide(c, false) === 'top').length,
                    inputs.filter(c => getSide(c, true) === 'bottom').length + outputs.filter(c => getSide(c, false) === 'bottom').length
                ) + 1);
                const height = Math.max(2, Math.max(
                    inputs.filter(c => getSide(c, true) === 'left').length + outputs.filter(c => getSide(c, false) === 'left').length,
                    inputs.filter(c => getSide(c, true) === 'right').length + outputs.filter(c => getSide(c, false) === 'right').length
                ) + 1);
                return { w: width, h: height, inputs: inputs.length, outputs: outputs.length };
             }
          }
          if (comp.type === ComponentType.SPLITTER || comp.type === ComponentType.MERGER) {
              // Dynamic Height based on bits
              const pins = comp.bitWidth; 
              // 1 grid unit per pin approx, but compacted. 
              // Let's say max(2, ceil(pins/2)) or just allow it to grow.
              const h = Math.max(2, pins + 1); // 1 pin per grid line
              return { w: 1, h: h, inputs: comp.type === ComponentType.MERGER ? pins : 1, outputs: comp.type === ComponentType.SPLITTER ? pins : 1 };
          }
          const def = COMPONENT_DEFINITIONS[comp.type];
          return { w: def.width, h: def.height, inputs: def.inputs, outputs: def.outputs };
      };

      const getPortPosition = (comp: CircuitComponent, index: number, type: 'input' | 'output'): PortPoint => {
        const dims = getComponentDimensions(comp);
        const w = dims.w * GRID_SIZE;
        const h = dims.h * GRID_SIZE;

        // Dynamic I/O positioning
        if ((comp.type === ComponentType.INPUT_SWITCH || comp.type === ComponentType.CLOCK) && type === 'output') {
            const side = comp.icPortSide || 'right';
            if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
            if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
            if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
            if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
        }
        if (comp.type === ComponentType.OUTPUT_LED && type === 'input') {
            const side = comp.icPortSide || 'left';
            if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
            if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
            if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
            if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
        }

        // Custom IC Logic (omitted for brevity, assume unchanged logic just using updated dims)
        if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
             const funcDef = libraryRef.current.find(f => f.id === comp.functionId);
             if (funcDef) {
                 const targetGroup = type === 'input' 
                    ? sortComponents(funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH), true)
                    : sortComponents(funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED), false);
                 const targetComp = targetGroup[index];
                 if (targetComp) {
                     const side = getSide(targetComp, type === 'input');
                     const sideGroup = targetGroup.filter(c => getSide(c, type === 'input') === side);
                     const localIndex = sideGroup.indexOf(targetComp);
                     const count = sideGroup.length;
                     const stepW = w / (count + 1);
                     const stepH = h / (count + 1);
                     if (side === 'top') return { x: comp.x + ((localIndex + 1) * stepW), y: comp.y, side: 'top' };
                     if (side === 'bottom') return { x: comp.x + ((localIndex + 1) * stepW), y: comp.y + h, side: 'bottom' };
                     if (side === 'left') return { x: comp.x, y: comp.y + ((localIndex + 1) * stepH), side: 'left' };
                     return { x: comp.x + w, y: comp.y + ((localIndex + 1) * stepH), side: 'right' };
                 }
             }
        }

        // Splitter / Merger Layout
        if (comp.type === ComponentType.SPLITTER) {
             // Input (Bus) on Left center
             if (type === 'input') return { x: comp.x, y: comp.y + h/2, side: 'left' };
             // Outputs (Bits) distributed on Right
             const step = h / (dims.outputs + 1);
             return { x: comp.x + w, y: comp.y + ((index + 1) * step), side: 'right' };
        }
        if (comp.type === ComponentType.MERGER) {
             // Inputs (Bits) distributed on Left
             const step = h / (dims.inputs + 1);
             if (type === 'input') return { x: comp.x, y: comp.y + ((index + 1) * step), side: 'left' };
             // Output (Bus) on Right center
             return { x: comp.x + w, y: comp.y + h/2, side: 'right' };
        }

        // Standard
        const count = type === 'input' ? dims.inputs : dims.outputs;
        const yStep = h / (count + 1);
        return {
          x: type === 'input' ? comp.x : comp.x + w,
          y: comp.y + ((index + 1) * yStep),
          side: type === 'input' ? 'left' : 'right'
        };
      };

      const drawArrow = (p: p5Types, x: number, y: number, side: PortSide, size: number) => {
          p.push();
          p.translate(x, y);
          if (side === 'right') p.rotate(0);
          else if (side === 'bottom') p.rotate(p.HALF_PI);
          else if (side === 'left') p.rotate(p.PI);
          else if (side === 'top') p.rotate(-p.HALF_PI);
          p.triangle(-size, -size/2, 0, 0, -size, size/2);
          p.pop();
      };

      const drawComponent = (p: p5Types, comp: CircuitComponent) => {
        const dims = getComponentDimensions(comp);
        const w = dims.w * GRID_SIZE;
        const h = dims.h * GRID_SIZE;
        const inputs = dims.inputs;
        const outputs = dims.outputs;
        const py = 6;
        const padX = 4;
        const effectiveH = h - (py * 2);

        p.push();
        p.translate(comp.x, comp.y);

        // -- Component Body Rendering --
        p.fill(COLOR_COMPONENT_BG);
        p.stroke(COLOR_COMPONENT_STROKE);
        p.strokeWeight(2);

        if (comp.type === ComponentType.SPLITTER || comp.type === ComponentType.MERGER) {
            // Trapezoid Shape
            p.beginShape();
            if (comp.type === ComponentType.SPLITTER) {
                // Wide Left (Bus), Narrow Right (Bits)? Or just Rect?
                // Standard symbol: Trapezoid wider at bits side usually, but let's do a simple rect with distinct fill
                p.fill('#f1f5f9');
                p.rect(0, 0, w, h, 4);

                // Draw internal lines fanning out
                p.stroke(COLOR_GRID);
                p.strokeWeight(1);
                const busY = h/2;
                const step = h / (outputs + 1);
                for(let i=0; i<outputs; i++) {
                   const bitY = (i+1)*step;
                   p.line(w*0.2, busY, w*0.8, bitY);
                }
            } else {
                p.fill('#f1f5f9');
                p.rect(0, 0, w, h, 4);

                // Fan in
                p.stroke(COLOR_GRID);
                p.strokeWeight(1);
                const busY = h/2;
                const step = h / (inputs + 1);
                for(let i=0; i<inputs; i++) {
                   const bitY = (i+1)*step;
                   p.line(w*0.2, bitY, w*0.8, busY);
                }
            }
            p.endShape();

            p.fill('#475569'); p.noStroke(); p.textAlign(p.CENTER, p.CENTER);
            p.text(comp.bitWidth + "b", w/2, h/2);

        } else if (comp.type === ComponentType.INPUT_SWITCH) {
            const val = comp.outputValues[0];
            const side = comp.icPortSide || 'right';
            const isBus = comp.bitWidth > 1;

            // Draw Connection Line
            p.stroke(val > 0 ? (isBus ? COLOR_BUS_ON : COLOR_WIRE_ON) : COLOR_COMPONENT_STROKE);
            let portX = 0, portY = 0;
            if (side === 'right') { p.line(w - padX, h/2, w, h/2); portX = w; portY = h/2; }
            else if (side === 'left') { p.line(0, h/2, padX, h/2); portX = 0; portY = h/2; }
            else if (side === 'top') { p.line(w/2, 0, w/2, padX); portX = w/2; portY = 0; }
            else if (side === 'bottom') { p.line(w/2, h - padX, w/2, h); portX = w/2; portY = h; }

            p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, isBus ? 8 : 6);

            // Box
            p.stroke(val > 0 ? (isBus ? COLOR_BUS_ON : COLOR_WIRE_ON) : COLOR_COMPONENT_STROKE);
            p.fill(val > 0 ? (isBus ? COLOR_BUS_ON : COLOR_WIRE_ON) : COLOR_COMPONENT_BG);
            p.rect(padX, py, w - (padX*2), effectiveH, 4); 

            // Text
            p.noStroke();
            p.fill(val > 0 ? '#fff' : '#475569');
            p.textSize(9);
            p.push(); p.translate(w/2, h/2);
            if (side === 'top' || side === 'bottom') p.rotate(-p.HALF_PI);

            if (isBus) {
                p.text("0x" + val.toString(16).toUpperCase(), 0, 0);
            } else {
                p.text(val ? "ON" : "OFF", 0, 0);
            }
            p.pop();

        } else if (comp.type === ComponentType.HEX_DISPLAY) {
             const val = comp.inputValues[0] || 0;
             const side = comp.icPortSide || 'left';

             // Input Port
             p.stroke(COLOR_COMPONENT_STROKE);
             let portX = 0, portY = 0;
             if (side === 'left') { p.line(0, h/2, padX, h/2); portX = 0; portY = h/2; }
             // ... simplify other sides for hex for now
             else { p.line(0, h/2, padX, h/2); } 

             p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, comp.bitWidth > 1 ? 8 : 6);

             p.fill('#0f172a'); p.stroke('#334155'); p.rect(padX, py, w - (padX*2), effectiveH, 4);
             p.noStroke(); p.fill('#ef4444'); p.textSize(14);

             let label = val.toString(16).toUpperCase();
             if (comp.bitWidth > 16) label = "0x" + label; // Prefix large numbers

             p.text(label, w/2, h/2 + 1);

        } else if (comp.type === ComponentType.OUTPUT_LED) {
             const val = comp.inputValues[0];
             const side = comp.icPortSide || 'left';
             const isBus = comp.bitWidth > 1;

             p.stroke(COLOR_COMPONENT_STROKE);
             let portX = 0, portY = 0;
             if (side === 'right') { p.line(w - padX, h/2, w, h/2); portX = w; portY = h/2; }
             else if (side === 'left') { p.line(0, h/2, padX, h/2); portX = 0; portY = h/2; }
             else if (side === 'top') { p.line(w/2, 0, w/2, padX); portX = w/2; portY = 0; }
             else if (side === 'bottom') { p.line(w/2, h - padX, w/2, h); portX = w/2; portY = h; }

             p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, isBus ? 8 : 6);

             p.noStroke();
             const r = (Math.min(w, h) - (padX * 2)) / 2;
             if (val > 0) {
                p.fill(isBus ? COLOR_BUS_ON : '#f59e0b'); 
                // Glow
                const c = p.color(isBus ? COLOR_BUS_ON : '#f59e0b');
                c.setAlpha(80);
                p.fill(c);
                p.circle(w/2, h/2, r * 2.5);
             }

             p.fill(val > 0 ? (isBus ? COLOR_BUS_ON : COLOR_WIRE_ON) : '#334155');
             p.circle(w/2, h/2, r * 2);

             if (isBus) {
                 p.fill('#fff'); p.textSize(8);
                 p.text(val.toString(16).toUpperCase(), w/2, h/2);
             }

        } else if (['AND', 'NAND', 'OR', 'NOR', 'NOT', 'XOR'].includes(comp.type)) {
             // Standard Gates
             const isNegated = ['NAND', 'NOR', 'NOT'].includes(comp.type);
             const bubbleR = 4;
             let bodyW = w;
             if (isNegated) bodyW = w - (bubbleR*2) - 2;

             // Draw Shape (Same as before)
             if (comp.type === 'AND' || comp.type === 'NAND') {
                 p.beginShape(); p.vertex(0, py); p.vertex(bodyW * 0.5, py);
                 (p as any).bezierVertex(bodyW, py, bodyW, h - py, bodyW * 0.5, h - py); p.vertex(0, h - py); p.endShape(p.CLOSE);
             } else if (comp.type === 'NOT') {
                 (p as any).triangle(0, py, 0, h - py, bodyW, h / 2);
             } else if (comp.type === 'OR' || comp.type === 'NOR') {
                 p.beginShape(); p.vertex(0, py); (p as any).bezierVertex(5, h * 0.25, 5, h * 0.75, 0, h - py);
                 (p as any).bezierVertex(w * 0.5, h - py, bodyW, h/2 + (effectiveH/4), bodyW, h/2);
                 (p as any).bezierVertex(bodyW, h/2 - (effectiveH/4), w * 0.5, py, 0, py); p.endShape(p.CLOSE);
             } else if (comp.type === 'XOR') {
                p.noFill(); p.beginShape(); p.vertex(0, py); (p as any).bezierVertex(5, h * 0.25, 5, h * 0.75, 0, h - py); p.endShape();
                p.fill(COLOR_COMPONENT_BG); p.beginShape(); p.vertex(4, py); (p as any).bezierVertex(9, h * 0.25, 9, h * 0.75, 4, h - py);
                (p as any).bezierVertex((w * 0.5) + 4, h - py, bodyW, h/2 + (effectiveH/4), bodyW, h/2);
                (p as any).bezierVertex(bodyW, h/2 - (effectiveH/4), (w * 0.5) + 4, py, 4, py); p.endShape(p.CLOSE);
             }
             if (isNegated) {
                 p.fill(COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE);
                 p.circle(w - bubbleR - 1, h / 2, bubbleR*2);
             }

             // Show Bit Width if > 1
             if (comp.bitWidth > 1) {
                 p.noStroke(); p.fill('#64748b'); p.textSize(8);
                 p.text(comp.bitWidth, w/2, h/2);
             }

        } else if (comp.type === ComponentType.CUSTOM_IC) {
            // IC Draw
            p.rect(0, 0, w, h, 4);
            p.fill('#1e293b'); p.noStroke();
            p.textSize(12); p.textStyle(p.BOLD);
            p.text(comp.customLabel || "IC", w/2, h/2);
            // Draw pins... (omitted detailed pin drawing for brevity, assumes standard pin logic works)
        } else if (comp.type === ComponentType.CLOCK) {
            // Clock Draw
            const isOn = comp.outputValues[0];
            p.rect(padX, py, w-(padX*2), effectiveH, 4);
             p.noFill(); p.stroke(isOn ? COLOR_WIRE_ON : '#64748b'); p.strokeWeight(2);
             const cx = padX + (w-padX*2)/2; const cy = py + effectiveH/2;
             p.beginShape(); p.vertex(cx - 8, cy + 4); p.vertex(cx - 4, cy + 4); p.vertex(cx - 4, cy - 4); p.vertex(cx + 4, cy - 4); p.vertex(cx + 4, cy + 4); p.vertex(cx + 8, cy + 4); p.endShape();
        }

        // Custom Labels
        if (comp.customLabel && comp.type !== ComponentType.CUSTOM_IC && comp.type !== ComponentType.INPUT_SWITCH && comp.type !== ComponentType.OUTPUT_LED && comp.type !== ComponentType.CLOCK) {
          p.noStroke(); p.fill('#1e293b'); p.textSize(12); p.textStyle(p.BOLD);
          p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2);
          p.textAlign(p.CENTER, p.CENTER); p.textStyle(p.NORMAL);
        }

        // Draw Ports (Nodes) for gates / Splitters
        const drawNode = (x: number, y: number, isBus: boolean) => {
            p.noStroke();
            p.fill('#64748b');
            p.circle(x, y, isBus ? 8 : 4);
        };

        if (comp.type !== ComponentType.CUSTOM_IC && comp.type !== ComponentType.INPUT_SWITCH && comp.type !== ComponentType.OUTPUT_LED && comp.type !== ComponentType.CLOCK) {
            for (let i = 0; i < inputs; i++) {
               const pos = getPortPosition(comp, i, 'input');
               // Splitter input is bus, Merger inputs are bits
               // Standard Gate inputs match comp bitwidth
               let isBus = comp.bitWidth > 1;
               if (comp.type === ComponentType.MERGER) isBus = false;
               if (comp.type === ComponentType.SPLITTER) isBus = true;

               drawNode(pos.x - comp.x, pos.y - comp.y, isBus);
            }
            for (let i = 0; i < outputs; i++) {
               const pos = getPortPosition(comp, i, 'output');
               let isBus = comp.bitWidth > 1;
               if (comp.type === ComponentType.SPLITTER) isBus = false;
               if (comp.type === ComponentType.MERGER) isBus = true;

               drawNode(pos.x - comp.x, pos.y - comp.y, isBus);
            }
        }

        p.pop();
      };

      const getHoveredPort = (wx: number, wy: number): { compId: string, portIndex: number, type: 'input'|'output' } | null => {
        const HIT_RADIUS = 12;
        for (const comp of componentsRef.current) {
          const dims = getComponentDimensions(comp);
          for (let i = 0; i < dims.inputs; i++) {
            const pos = getPortPosition(comp, i, 'input');
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'input' };
          }
          for (let i = 0; i < dims.outputs; i++) {
            const pos = getPortPosition(comp, i, 'output');
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'output' };
          }
        }
        return null;
      };

      const getHoveredComponent = (wx: number, wy: number): string | null => {
        for (const comp of componentsRef.current) {
          const dims = getComponentDimensions(comp);
          if (wx > comp.x && wx < comp.x + (dims.w * GRID_SIZE) &&
              wy > comp.y && wy < comp.y + (dims.h * GRID_SIZE)) {
            return comp.id;
          }
        }
        return null;
      };

      // -- EVENTS (Drag, Touch, etc.) --
      // (Mostly identical to original, just ensuring updateComponentPos respects grid)

      const updateComponentPos = (sx: number, sy: number) => {
          isDraggingComp.current = true;
          const mouseWorld = screenToWorld(sx, sy);
          const comp = componentsRef.current.find(c => c.id === activeDragId.current);
          if (comp) {
            comp.x = Math.round((mouseWorld.x - dragOffset.current.x) / GRID_SIZE) * GRID_SIZE;
            comp.y = Math.round((mouseWorld.y - dragOffset.current.y) / GRID_SIZE) * GRID_SIZE;
          }
      };

      (p as any).touchStarted = (e: any) => {
        if (e.target !== (p as any).canvas) {
          isCanvasInteraction = false;
          return true;
        }
        isCanvasInteraction = true;
        if (p.touches.length === 2) {
          const t0 = p.touches[0] as any;
          const t1 = p.touches[1] as any;
          // @ts-ignore
          pinchDistStart = p.dist(t0.x, t0.y, t1.x, t1.y);
        } else if (p.touches.length === 1) {
          const t0 = p.touches[0] as any;
          lastTouchX = t0.x;
          lastTouchY = t0.y;
          p.mousePressed(undefined);
        }
        return false;
      };

      (p as any).touchMoved = (e: any) => {
        if (!isCanvasInteraction) return true;
        if (p.touches.length === 2) {
          const t0 = p.touches[0] as any;
          const t1 = p.touches[1] as any;
          // @ts-ignore
          const currentDist = p.dist(t0.x, t0.y, t1.x, t1.y);
          if (pinchDistStart > 0) {
            const scaleFactor = currentDist / pinchDistStart;
            const newZoom = Math.min(Math.max(viewportRef.current.zoom * scaleFactor, 0.1), 5.0);
            // @ts-ignore
            const cx = (t0.x + t1.x) / 2;
            // @ts-ignore
            const cy = (t0.y + t1.y) / 2;
            const wx = (cx - viewportRef.current.x) / viewportRef.current.zoom;
            const wy = (cy - viewportRef.current.y) / viewportRef.current.zoom;
            viewportRef.current.x = cx - wx * newZoom;
            viewportRef.current.y = cy - wy * newZoom;
            viewportRef.current.zoom = newZoom;
            pinchDistStart = currentDist;
          }
        } else if (p.touches.length === 1) {
          const t0 = p.touches[0] as any;
          const tx = t0.x;
          const ty = t0.y;
          if (activeDragId.current) {
            updateComponentPos(tx, ty);
          } else if (isPanningRef.current) {
            const dx = tx - lastTouchX;
            const dy = ty - lastTouchY;
            viewportRef.current.x += dx;
            viewportRef.current.y += dy;
          }
          lastTouchX = tx;
          lastTouchY = ty;
        }
        return false;
      };

      (p as any).touchEnded = () => {
        if (!isCanvasInteraction) return true;
        if (p.touches.length === 0) p.mouseReleased();
        return false;
      };

      (p as any).mouseWheel = (e: any) => {
        const zoomSensitivity = 0.001;
        const zoomFactor = Math.exp(-e.delta * zoomSensitivity);
        const newZoom = Math.min(Math.max(viewportRef.current.zoom * zoomFactor, 0.1), 5.0);
        const wx = (p.mouseX - viewportRef.current.x) / viewportRef.current.zoom;
        const wy = (p.mouseY - viewportRef.current.y) / viewportRef.current.zoom;
        viewportRef.current.zoom = newZoom;
        viewportRef.current.x = p.mouseX - wx * newZoom;
        viewportRef.current.y = p.mouseY - wy * newZoom;
        return false;
      };

      p.mousePressed = (e: any) => {
        if (e && e.target !== (p as any).canvas) return;
        if (p.mouseX < 0 || p.mouseX > p.width || p.mouseY < 0 || p.mouseY > p.height) return;

        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
        isDraggingComp.current = false;
        isPanningRef.current = false;

        const port = getHoveredPort(mouseWorld.x, mouseWorld.y);
        if (port) {
            if (port.type === 'input') {
                const existingWireIndex = wiresRef.current.findIndex(w => w.toCompId === port.compId && w.toPortIndex === port.portIndex);
                if (existingWireIndex !== -1) {
                    const existingWire = wiresRef.current[existingWireIndex];
                    wiresRef.current.splice(existingWireIndex, 1);
                    wiringStart.current = {
                        compId: existingWire.fromCompId,
                        portIndex: existingWire.fromPortIndex,
                        type: 'output'
                    };
                    return;
                }
            }
          wiringStart.current = port;
          return;
        }

        const compId = getHoveredComponent(mouseWorld.x, mouseWorld.y);
        if (compId) {
          if (toolRef.current === 'DELETE') {
             componentsRef.current = componentsRef.current.filter(c => c.id !== compId);
             wiresRef.current = wiresRef.current.filter(w => w.fromCompId !== compId && w.toCompId !== compId);
             if (selectedCompId.current === compId && onSelectionChange) onSelectionChange(null);
             if (activeDragId.current === compId) activeDragId.current = null;
             return;
          }
          const comp = componentsRef.current.find(c => c.id === compId);
          if (comp) {
             selectedCompId.current = compId;
             activeDragId.current = compId; // Start Dragging
             dragOffset.current = { x: mouseWorld.x - comp.x, y: mouseWorld.y - comp.y };
             if (onSelectionChange) onSelectionChange(comp);
          }
          return;
        }
        selectedCompId.current = null;
        activeDragId.current = null;
        if (onSelectionChange) onSelectionChange(null);
        isPanningRef.current = true;
      };

      p.mouseDragged = () => {
        if (p.touches.length > 0) return;
        if (isPanningRef.current) {
          viewportRef.current.x += (p.mouseX - p.pmouseX);
          viewportRef.current.y += (p.mouseY - p.pmouseY);
          return;
        }
        if (activeDragId.current) {
           updateComponentPos(p.mouseX, p.mouseY);
        }
      };

      p.mouseReleased = () => {
        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);

        if (activeDragId.current && !isDraggingComp.current) {
          const comp = componentsRef.current.find(c => c.id === activeDragId.current);
          if (comp) {
            if (comp.type === ComponentType.INPUT_SWITCH) {
              // Interactive toggle:
              // If single bit: 0 -> 1 -> 0
              // If multi-bit: Prompt? Or +1? 
              // For now, let's just do toggle of LSB or +1
              if (comp.bitWidth === 1) {
                  comp.outputValues[0] = comp.outputValues[0] ? 0 : 1;
              } else {
                  // Simple increment for testing multi-bit
                  let val = (comp.outputValues[0] || 0) + 1;
                  const max = Math.pow(2, comp.bitWidth) - 1;
                  if (val > max) val = 0;
                  comp.outputValues[0] = val;
              }
            }
          }
        }

        activeDragId.current = null;
        isDraggingComp.current = false;
        isPanningRef.current = false;

        if (wiringStart.current) {
          const endPort = getHoveredPort(mouseWorld.x, mouseWorld.y);
          if (endPort && endPort.compId !== wiringStart.current.compId) {
            let src = wiringStart.current.type === 'output' ? wiringStart.current : endPort;
            let dst = wiringStart.current.type === 'input' ? wiringStart.current : endPort;

            if (src.type === 'output' && dst.type === 'input') {
              const exists = wiresRef.current.some(w => 
                w.toCompId === dst.compId && w.toPortIndex === dst.portIndex
              );
              if (!exists) {
                wiresRef.current.push({
                  id: crypto.randomUUID(),
                  fromCompId: src.compId,
                  fromPortIndex: src.portIndex,
                  toCompId: dst.compId,
                  toPortIndex: dst.portIndex,
                  value: 0
                });
              }
            }
          }
          wiringStart.current = null;
        }
      };
    };

    p5InstanceRef.current = new p5Constructor(sketch, containerRef.current);
    return () => { p5InstanceRef.current?.remove(); };
  }, []); 

  return (
    <div 
      ref={containerRef} 
      className="w-full h-full cursor-crosshair touch-none select-none pointer-events-auto" 
      onDragOver={handleDragOver}
      onDrop={handleDrop}
    />
  );
});

export default LogicCanvas;
